-- Add authored factual context; preserve every decision, vote, effect and completed outcome.
with context as (select * from jsonb_to_recordset($casecontext$[{"case_key": "bank-legal-2026-001", "title": "Заповедный грант", "situation": "В Адыгее грант экотуристической фирме предложено перечислить до отбора получателей: сезон начинается завтра, а критерии комиссии ещё не опубликованы.\n\nВ учебном досье указаны 2,4 млн ₽ поддержки и три потенциальных получателя. Одна компания уже заказала экскурсионные автобусы, две другие не знают о конкурсе. Срок открытия маршрута не совпадает со сроком обязательного оформления расхода. В распоряжении участника есть проект порядка, письмо предпринимателя и календарь сезона; нужно выбрать действие до передачи платёжного поручения."}, {"case_key": "bank-legal-2026-002", "title": "Заводская льгота", "situation": "В Башкортостане губернатор обещает конкретному заводу освободить прибыль от налога письмом администрации. Регионального закона о льготе нет.\n\nДиректор завода показывает обещание сохранить 70 рабочих мест и просит налогового инспектора применить письмо к ближайшему авансовому платежу. В налоговых регистрах прибыль уже определена. Юрист администрации не нашёл опубликованного акта с условиями льготы. До срока платежа осталось пять дней, а депутаты готовы рассмотреть предложение на заседании через неделю."}, {"case_key": "bank-legal-2026-003", "title": "Байкальское софинансирование", "situation": "В Бурятии федеральная субсидия на очистные требует регионального софинансирования. В проекте бюджета этой строки нет, подрядчик просит аванс.\n\nВ учебном расчёте строительство стоит 90 млн ₽, из которых 18 млн ₽ должен предоставить регион. Федеральное соглашение содержит сроки ввода объекта и условия перечисления средств. Подрядчик подготовил площадку, но казначейство не получило подтверждения ассигнований. Участнику переданы проект соглашения, смета и выдержка из регионального бюджета; решение требуется до подписания авансового платежа."}, {"case_key": "bank-legal-2026-004", "title": "Курортные дни", "situation": "В Республике Алтай муниципальный совет предлагает туристический налог 5% уже в 2026 году. Отель включил сумму в новый прайс.\n\nСовет обсуждает проект решения на очередной сессии, а владельцы гостиниц уже уведомили гостей о новых ценах. В таблице администратора смешаны предельная ставка соответствующего года и ставка будущего периода. Один турист забронировал номер заранее и требует объяснить изменение стоимости. Участнику доступны календарь введения налога, проект муниципального акта и расчёт на одну ночёвку."}, {"case_key": "bank-legal-2026-005", "title": "Целевой водопровод", "situation": "В Дагестане субвенцию на переданное полномочие хотят направить на городской фонтан. Администрация ссылается на одинаковую водную тематику.\n\nСредства поступили с кодом целевого назначения, отдельным отчётом и сроком выполнения переданного полномочия. Проект фонтана стоит 6 млн ₽ и поддерживается частью жителей, но отсутствует в соглашении о субвенции. Бухгалтер предлагает поменять название расхода в заявке, сохранив его содержание. Участник проверяет соглашение, смету и объём ещё неисполненных обязательств переданных полномочий."}, {"case_key": "bank-legal-2026-006", "title": "Смета школы", "situation": "Казённая школа Ингушетии принимает обязательство на ремонт сверх доведённых лимитов. Директор обещает закрыть разницу будущей платной кружковой работой.\n\nПо учебной смете школе доведено 3 млн ₽, а подрядчик предлагает договор на 4,2 млн ₽. Акт обследования подтверждает необходимость ремонта, однако собственные доходы следующего года ещё не получены. Платёжный график предусматривает аванс до начала работ. На столе у участника лежат смета, лимиты и договор; директор просит решить вопрос до окончания срока предложения подрядчика."}, {"case_key": "bank-legal-2026-007", "title": "Сезонный канат", "situation": "В Кабардино-Балкарии концессионер канатной дороги требует гарантию доходности на 15 лет. Будущие выплаты не включены в бюджетный прогноз.\n\nВ проекте соглашения есть компенсация недополученной выручки при снижении туристического потока. Сумма может достигнуть 12 млн ₽ в год, но приложение к прогнозу содержит только расходы текущего сезона. Банк считает обещание региона достаточным обеспечением кредита. Участник получил три сценария посещаемости и должен оценить не только первый платёж, но и обязательства будущих периодов."}, {"case_key": "bank-legal-2026-008", "title": "Пастбище и кадастр", "situation": "В Калмыкии земли сельскохозяйственного назначения используют по назначению. Муниципалитет начислил земельный налог по ставке 1,5% без проверки категории.\n\nВ кадастровой выписке указаны категория и разрешённое использование, а акт осмотра подтверждает выпас скота. Налоговое уведомление сформировано по шаблону для иного участка. Собственник просит ответ до срока уплаты и не оспаривает площадь земли. Участнику доступны выписка, муниципальные ставки и расчёт; спор касается правового основания ставки, а не размера дохода хозяйства."}, {"case_key": "bank-legal-2026-009", "title": "Грант родственнику", "situation": "В Карачаево-Черкесии член комиссии по субсидиям рассматривает заявку фирмы своего брата и участвует в оценивании. Это обнаружено до утверждения протокола.\n\nДве заявки отличаются по оборудованию и плану занятости, а оценочные листы ещё не подписаны. Член комиссии сообщил о родстве только после вопроса секретаря и предложил голосовать «как обычный эксперт». В составе комиссии есть замещающий участник. Нужно определить порядок работы с заявкой, уведомлением и протоколом так, чтобы решение можно было проверить после распределения средств."}, {"case_key": "bank-legal-2026-010", "title": "Лесной доход", "situation": "В Карелии предлагают оставить в местном бюджете все платежи по аренде лесных участков независимо от принадлежности участка и норм зачисления.\n\nВ учебном реестре есть федеральный лесной участок и участок иной публичной собственности. Проект доходной части объединяет оба договора аренды в одну строку местных поступлений. Финансист намерен направить ожидаемые деньги на освещение поселения. Участнику переданы выписки о собственности и условия аренды; необходимо проверить, какие поступления действительно доступны этому бюджету."}, {"case_key": "bank-legal-2026-011", "title": "Северный резерв", "situation": "В Коми резервный фонд исполнительной власти хотят использовать для ежегодного планового праздника. Непредвиденных обстоятельств не возникло.\n\nПраздник проводится каждый год, дата известна с начала бюджетного планирования. Организатор не получил ассигнования по обычной программе и предлагает провести оплату через резерв. В фонде предусмотрены деньги на внезапные аварии коммунальной инфраструктуры. Участник изучает положение о резервном фонде, заявку и календарь расходов до подготовки распоряжения об использовании средств."}, {"case_key": "bank-legal-2026-012", "title": "Цифровое имущество", "situation": "В Марий Эл бухгалтер включил права на программу для ЭВМ в базу налога на имущество организаций наряду с недвижимостью.\n\nКомпания приобрела офисное здание и исключительное право на программу по разным договорам. В учётной ведомости оба объекта объединены по признаку высокой стоимости. Инспектор просит пояснение о составе налоговой базы за квартал. Участник получает бухгалтерские документы и характеристики активов; решение должно учитывать вид объекта, а не только строку его отражения в общем отчёте."}, {"case_key": "bank-legal-2026-013", "title": "Спорная дотация", "situation": "В Мордовии муниципалитет получает дотацию на выравнивание. Региональный чиновник требует вернуть её за несогласованный цвет благоустройства.\n\nДеньги перечислены на выравнивание бюджетной обеспеченности, а не по соглашению о конкретном благоустройстве. Цвет покрытия выбран местным советом в рамках отдельного проекта. Письмо о возврате не содержит расчёта нарушения и ссылки на условие предоставления дотации. Участнику нужно сопоставить назначение трансферта, полномочия сторон и документы требования до ответа финансовому органу."}, {"case_key": "bank-legal-2026-014", "title": "Тепло на мерзлоте", "situation": "В Якутии авария теплотрассы требует срочного ремонта. Управление хочет применить закупку у единственного поставщика без описания аварии и объёма срочных работ.\n\nАкт диспетчера фиксирует разрыв трубы и угрозу остановки отопления нескольких домов. Подрядчик готов устранить аварийный участок за 48 часов, но в предложении дополнительно указан плановый ремонт соседней магистрали. Финансирование срочной части определено в резерве. Участник получил фотографии, дефектную ведомость и две сметы; необходимо отделить аварийную потребность от работ, которые могут пройти обычную процедуру."}, {"case_key": "bank-legal-2026-015", "title": "Гарантия футбольному клубу", "situation": "В Северной Осетии предлагают государственную гарантию по кредиту клуба без анализа финансового состояния принципала и бюджетного оформления.\n\nКлуб просит обеспечение кредита на строительство тренировочной базы сроком на семь лет. В пакете есть презентация посещаемости, но отсутствует проверка финансового положения и обеспечение обратных требований. Предельный объём гарантий в учебном бюджете уже частично занят. Участнику переданы проект гарантии, долговая книга и заявка банка; решение нужно принять до выпуска письма о поддержке."}, {"case_key": "bank-legal-2026-016", "title": "Платёж за станок", "situation": "В Татарстане промышленная субсидия возмещает покупку оборудования. Заявитель представил один и тот же счёт для двух программ возмещения.\n\nОба отчёта относятся к одному станку, одной накладной и одной дате оплаты. Первая программа покрывает часть покупки, вторая рассчитана на другой набор подтверждённых затрат. Получатель считает, что разные названия программ допускают повторное возмещение. Участник проверяет соглашения и документы об оплате до утверждения суммы; отдельный вопрос — корректность уже представленного отчёта."}, {"case_key": "bank-legal-2026-017", "title": "Дорога в долг", "situation": "В Тыве банк предлагает кредит, после которого плановый долг превысит допустимый для конкретного региона предел. Ответственный сравнил только процентную ставку.\n\nВ таблице заимствований не учтены два действующих обязательства, а доходная база включает целевые поступления. Кредит дешевле альтернативы на один процентный пункт, но требует погашения в следующем году. Финансовый орган должен представить расчёт допустимого объёма долга на заседании. Участнику доступны долговая книга и проект доходов; выбрать действие нужно до подписания кредитного договора."}, {"case_key": "bank-legal-2026-018", "title": "Оружейный заказ", "situation": "В Удмуртии открытый конкурс на поставку содержит сведения ограниченного доступа. Заказчик намерен опубликовать весь технический пакет вместе с извещением.\n\nПоставщик прислал техническое приложение, часть которого отмечена как сведения ограниченного доступа. Электронная площадка предлагает общий режим размещения файлов. Сотрудник закупок хочет ускорить публикацию, чтобы не сорвать производственный график. Участник получил отметки о режиме информации и проект документации; необходимо определить процедуру и состав раскрываемых сведений до отправки извещения."}, {"case_key": "bank-legal-2026-019", "title": "Угольный вычет", "situation": "В Хакасии предприятие просит уменьшить НДПИ на расходы, не подтверждённые документами и не относящиеся к предусмотренному вычету.\n\nПредприятие предъявило платежи за ремонт административного здания вместе с расходами производственного участка. Документы о назначении затрат представлены не полностью. В декларации уже рассчитана сумма предполагаемого уменьшения налога. Участнику доступны счета, акты и перечень заявленных расходов; решение требуется до подачи уточнений, с проверкой связи каждой суммы с установленными условиями вычета."}, {"case_key": "bank-legal-2026-020", "title": "Кассовый разрыв", "situation": "В Чечне временно не хватает денег на уже предусмотренные обязательства. Участник называет кассовый разрыв новым дефицитом бюджета и предлагает отменить все расходы.\n\nКассовый план показывает поступление доходов через десять дней, тогда как зарплата и договорные платежи должны пройти на этой неделе. Годовые ассигнования и ожидаемые доходы не изменились. В служебной записке смешаны остаток денег на счёте и годовой баланс. Участник должен выбрать порядок исполнения обязательств на коротком горизонте, используя кассовый план, платёжный календарь и условия допустимого финансирования."}, {"case_key": "bank-legal-2026-021", "title": "Экспортный аванс", "situation": "В Чувашии завод получил аванс от иностранного покупателя. Бухгалтер автоматически применил нулевой НДС ко всем внутренним продажам этого месяца.\n\nВ одном месяце завод реализовал продукцию за рубеж и покупателям внутри страны. Экспортный комплект подтверждений ещё собирается, но бухгалтер перенёс одну ставку на весь журнал продаж. Покупатель внутренней партии просит корректный счёт-фактуру. Участник получает договоры, отгрузочные документы и реестр аванса; важны вид операции и её подтверждение, а не валюта отдельного поступления."}, {"case_key": "bank-legal-2026-022", "title": "Агростраховой платёж", "situation": "В Алтайском крае возмещение агростраховых затрат заявляет хозяйство без действующего договора страхования. Оно предлагает позже донести полис.\n\nХозяйство представило расчёт затрат и письмо страхового агента, но договор ещё не вступил в силу. В регионе начинается посевная, и фермер просит аванс на семена. Порядок поддержки содержит перечень подтверждающих документов и срок подачи. Участник должен решить, какой пакет можно принять сейчас, опираясь на фактические расходы и условия программы, до перечисления бюджетных средств."}, {"case_key": "bank-legal-2026-023", "title": "Пляжная плата", "situation": "В Краснодарском крае администрация вводит обязательный сбор за проход к общедоступному берегу, называя его неналоговым доходом бюджета.\n\nНа входе установлена будка оплаты, а альтернативный проход перекрыт ограждением арендатора. Местный бюджет планирует получить 1,8 млн ₽ за сезон. В проекте акта термин «услуга» применяется к самому проходу, без отдельной услуги посетителю. Участнику переданы схема берега, договор аренды и проект решения; нужно проверить правовую природу платежа и доступ граждан."}, {"case_key": "bank-legal-2026-024", "title": "Нефтяная цена", "situation": "Красноярский край включил разовое поступление от продажи имущества в постоянную базу финансирования зарплат. Следующие три года продажи не ожидается.\n\nПродажа склада даст учебному бюджету 140 млн ₽ в первом году. В расходном плане на эту сумму назначены постоянные выплаты, а повторного имущества для продажи нет. При ухудшении доходов обязательства по зарплате сохранятся. Участник получил трёхлетний прогноз и ведомость имущества; решение требует сопоставить устойчивость источника с характером финансируемого расхода."}, {"case_key": "bank-legal-2026-025", "title": "Портовая льгота", "situation": "В Приморском крае инвестору обещано освобождение от всех федеральных налогов региональным соглашением. Заявитель просит заверить обещание печатью.\n\nИнвестор планирует склад и просит приложить письмо администрации к кредитному досье. В перечне обещанных льгот смешаны федеральные и региональные платежи. Опубликованного основания для части обещаний нет, но презентация уже распространяется среди партнёров. Участник сопоставляет соглашение и полномочия публичного органа до заверения документа; коммерческий эффект обещания не заменяет его правовое основание."}, {"case_key": "bank-legal-2026-026", "title": "Минеральный курорт", "situation": "В Ставропольском крае гостиница начисляет туристический налог человеку, подпадающему под федеральное освобождение, поскольку совет не продублировал льготу.\n\nПостоялец предъявил документ, подтверждающий основание освобождения, до окончательного расчёта гостиницы. В программе учёта предусмотрен только перечень из местного решения. Менеджер опасается потерять выручку и просит муниципалитет подтвердить порядок. Участник получает расчёт проживания и подтверждающий документ; необходимо определить применимое основание льготы и действия по уже начисленной сумме."}, {"case_key": "bank-legal-2026-027", "title": "Мостовой эскроу", "situation": "В Хабаровском крае аванс подрядчику направляют на обычный счёт, хотя условия финансирования требуют казначейского сопровождения.\n\nКонтракт предусматривает аванс 30 млн ₽ на материалы, с отдельным порядком сопровождения. Подрядчик направил реквизиты своего обычного банковского счёта и обещал отчитаться накладными позднее. Финансовый орган видит несоответствие условиям выделения денег. Участник изучает контракт, соглашение о финансировании и реквизиты до платежа, учитывая назначение средств и правила их дальнейшего движения."}, {"case_key": "bank-legal-2026-028", "title": "Неподписанная субсидия", "situation": "В Амурской области субсидию обещали устно. Получатель уже начал строительство и требует перечислить деньги без соглашения и проверок условий.\n\nВ переписке есть согласование идеи проекта и предварительная оценка объёма помощи. Соглашение не подписано, показатели результата и условия возврата не определены. Подрядчик выставил счёт за уже начатые работы заявителя. Участник получил письма, проект порядка поддержки и подтверждение расходов; нужно отделить фактические ожидания получателя от основания бюджетного обязательства."}, {"case_key": "bank-legal-2026-029", "title": "Ненецкий знаменатель", "situation": "Архангельская область сравнивает показатели долга с доходами, включая показатели автономного округа дважды. Расчёт используют для предельного заимствования.\n\nВ исходной таблице одна строка содержит данные области без автономного округа, а другая — консолидированный итог с округом. Аналитик складывает обе строки и получает завышенную доходную базу. От этого расчёта зависит допустимый объём нового кредита. Участник должен проверить границы показателей, единицы и источники, сохранив возможность повторить расчёт по тем же таблицам."}, {"case_key": "bank-legal-2026-030", "title": "Каспийская квота", "situation": "В Астраханской области фирма получила разрешение на водные биоресурсы, но рассчитывает сбор по вылову вместо показателей, установленных для этого разрешения.\n\nВ разрешении указаны виды ресурсов и объёмы, а журнал судна отражает меньший фактический улов. Бухгалтер уменьшил платежи пропорционально разнице и не проверил порядок расчёта сбора. Срок внесения очередной суммы приближается. Участнику переданы разрешение, журнал и расчёт; необходимо определить правовое основание базы и порядок исправления платежа при различии этих сведений."}, {"case_key": "bank-legal-2026-031", "title": "Восстановление склада", "situation": "В Белгородской области чрезвычайная помощь выделена на восстановление склада. Получатель направил её на приобретение нового автомобиля руководителя.\n\nВ соглашении перечислены восстановительные работы и требования к подтверждению затрат. Платёж за автомобиль обнаружен при проверке промежуточного отчёта, пока большая часть помощи ещё не освоена. Получатель объясняет покупку необходимостью руководителю ездить на объект. Участник получает смету, выписки и акт осмотра; решение касается назначения расхода и дальнейшей судьбы помощи, а не общей полезности машины."}, {"case_key": "bank-legal-2026-032", "title": "Пограничный автобус", "situation": "В Брянской области транспортную субсидию рассчитывают за рейсы, которые отменены. Перевозчик представил плановое расписание вместо фактических данных.\n\nВ учебном отчётном месяце фактически выполнено 62 рейса из 80 запланированных. Часть отмен связана с погодой, часть — с неисправностью автобуса. Порядок возмещения предусматривает расчёт подтверждённой транспортной работы. Участник получил путевые листы, расписание и заявку на субсидию; необходимо установить, какие данные использовать и как зафиксировать расхождения до перечисления средств."}, {"case_key": "bank-legal-2026-033", "title": "Музей без задания", "situation": "Во Владимирской области бюджетному музею уменьшают субсидию на задание, не меняя объём задания и не обосновывая изменение нормативных затрат.\n\nМузей должен провести то же число выставок и экскурсий, что предусмотрено действующим заданием. Уменьшение финансирования объясняется общим желанием экономии, без изменения расчёта нормативов. Сотрудники предупреждают о закрытии части экспозиции. Участник сопоставляет задание, расчёт затрат и проект соглашения; решение требуется до уведомления учреждения о новом объёме субсидии."}, {"case_key": "bank-legal-2026-034", "title": "Судебный лист", "situation": "В Волгоградской области казначейство получило исполнительный документ о взыскании с бюджетного учреждения. Финорган предлагает оставить его без регистрации.\n\nДокумент поступил с судебными реквизитами, заявлением взыскателя и сведениями о получателе. Учреждение просит «подождать переговоров», а срок дальнейших действий уже отсчитывается от поступления. В журнале входящих пока нет записи. Участник получает пакет взыскателя и письма сторон; нужно выбрать процедуру, которая обеспечивает учёт документа и исполнение применимых требований."}, {"case_key": "bank-legal-2026-035", "title": "Стальная переоценка", "situation": "В Вологодской области завод рассчитывает налог на имущество по остаточной стоимости объекта, для которого применима кадастровая база и утверждённый перечень.\n\nОбъект включён в опубликованный перечень, а компания использовала старую карточку основных средств. После переоценки остаточная стоимость существенно ниже кадастровой. Бухгалтер предлагает продолжить прежний расчёт до конца года. Участник изучает вид объекта, перечень соответствующего периода и налоговые регистры; важно определить применимое основание базы и период расчёта, а не выгодность суммы для предприятия."}, {"case_key": "bank-legal-2026-036", "title": "Садовый гектар", "situation": "В Воронежской области участок фактически используется для коммерческого склада, хотя заявитель требует льготной ставки как для садоводства.\n\nНа участке размещены ангар, погрузочная площадка и складские договоры с несколькими клиентами. В выписке сохранено прежнее разрешённое использование, а фактическая деятельность изменилась. Собственник ссылается на старое членство в садовом товариществе. Участнику переданы акт осмотра, выписка и ставки; спор требует сопоставить правовые условия льготы с подтверждённым использованием земли."}, {"case_key": "bank-legal-2026-037", "title": "Текстильная отсрочка", "situation": "В Ивановской области фабрика просит налоговую отсрочку. Администрация предлагает сама подписать её вместо уполномоченного налогового органа.\n\nУ фабрики снизилась выручка, и к заявлению приложены финансовые документы и план восстановления. В администрации готовы поддержать предприятие, но налоговое решение ещё не принято. Банк просит письменное подтверждение отсрочки для кредитного соглашения. Участник получает проект письма и заявление; требуется определить компетентного адресата и дальнейший порядок рассмотрения до обещания переноса срока."}, {"case_key": "bank-legal-2026-038", "title": "Байкальский ущерб", "situation": "В Иркутской области предприятие предлагает зачесть добровольный экологический платёж в счёт налога на прибыль без предусмотренного правового основания.\n\nФирма перечислила деньги на восстановление прибрежной территории добровольно, по отдельному соглашению. В расчёте налога бухгалтер механически вычел всю сумму из платежа, не проверив квалификацию расхода. Экологический проект подтверждён фотографиями, но это не налоговый расчёт. Участнику доступны соглашение, документы об оплате и регистры; нужно отделить общественно полезный результат от правового основания уменьшения налога."}, {"case_key": "bank-legal-2026-039", "title": "Особая зона", "situation": "В Калининградской области фирма требует льготу особой экономической зоны только по месту адреса. Статус резидента и условия деятельности не подтверждены.\n\nКомпания арендовала небольшой офис по нужному адресу, а основное производство находится за пределами заявленной деятельности. В реестре резидентов сведения о ней не найдены. Представитель просит применить льготу с даты аренды офиса. Участник получает договор, описание проекта и налоговый расчёт; необходимо проверить статус, период и условия права на специальный порядок, не ограничиваясь географическим адресом."}, {"case_key": "bank-legal-2026-040", "title": "Кластерный конкурс", "situation": "В Калужской области условия гранта требуют опыт производства изделия ровно 17 месяцев. Ограничение совпадает с опытом одной фирмы и не обосновано целью поддержки.\n\nКомиссия получила четыре заявки, из которых три отклоняются только по длительности опыта. В пояснении к порядку не показано, почему выбран именно такой срок. Предприятия предлагают подтвердить качество продукции испытаниями. Участнику доступны проект критериев и сравнительная таблица заявок; решение требуется до публикации результатов отбора и должно учитывать проверяемость условий доступа к поддержке."}, {"case_key": "bank-legal-2026-041", "title": "Рыбный рейс", "situation": "На Камчатке субсидируют доставку продуктов в труднодоступные районы. В отчёт перевозчика включены коммерческие туристические рейсы без доставки.\n\nПеревозчик объединил в одном реестре доставку продуктов, туристов и собственных сотрудников. Посадочные ведомости и грузовые документы позволяют разделить рейсы. В заявке на возмещение указана общая стоимость топлива. Участник должен сопоставить цель программы с каждым рейсом и документами о затратах до принятия отчёта; географическая удалённость сама по себе не делает любой рейс субсидируемым."}, {"case_key": "bank-legal-2026-042", "title": "Шахтёрский переход", "situation": "В Кузбассе планируют закрыть шахту с задолженностью по зарплате. Помощь регионального бюджета предложено перечислить собственнику без условий защиты работников.\n\nВ досье есть списки работников, задолженность по выплатам и план переобучения. Собственник просит 50 млн ₽ на «стабилизацию», без отдельных показателей использования средств. Муниципалитет опасается роста безработицы после остановки предприятия. Участник изучает цель поддержки, условия соглашения и контроль результата; требуется выбрать способ, связывающий бюджетное решение с фактическим положением работников."}, {"case_key": "bank-legal-2026-043", "title": "Лесной купон", "situation": "Кировская область выпускает облигации, но в презентации замалчивает условия погашения и объём действующего долга. Инвесторам предлагают устное обещание досрочного выкупа.\n\nВ проекте размещения есть срок обращения, размер купона и условия досрочного погашения, но рекламная презентация не совпадает с ним. Часть слушателей воспринимает облигацию как вклад с гарантированным досрочным возвратом. Финорган получил запрос о долговой нагрузке. Участнику переданы условия займа и долговая книга; необходимо определить раскрываемую информацию и порядок исправления сообщения инвесторам."}, {"case_key": "bank-legal-2026-044", "title": "Ювелирная касса", "situation": "В Костромской области малый бизнес смешивает выручку ювелирной торговли с деятельностью, для которой специальный режим допустим, и применяет его ко всем операциям.\n\nВ журнале продаж отдельно отражены ювелирные изделия и иная продукция мастерской. Регистрационные документы содержат несколько видов деятельности, но бухгалтер использует один налоговый расчёт для всей выручки. Контрагент запросил подтверждение режима. Участник проверяет применимость специального порядка к конкретным операциям и структуру учёта до сдачи отчётности, не делая вывод только по названию бизнеса."}, {"case_key": "bank-legal-2026-045", "title": "Курганский паводок", "situation": "В Курганской области на восстановление после паводка перечисляют помощь по списку домов без обследования повреждений. В списке есть непострадавший объект.\n\nКомиссия объехала часть улиц, но один адрес перенесён в список по устному сообщению. Фотографии этого дома не подтверждают повреждений, а владелец просит выплатить помощь вместе с соседями. Срок первого перечисления назначен на пятницу. Участнику доступны акты, фотографии и критерии помощи; необходимо определить, как проверить конкретный адрес и сохранить законное рассмотрение остальных заявок."}, {"case_key": "bank-legal-2026-046", "title": "Неиспользованный остаток", "situation": "Курская область получила целевой межбюджетный трансферт, который не использован к концу года. Чиновник предлагает автоматически потратить его в следующем году без решения о потребности.\n\nВ соглашении установлен срок использования, отчётность и порядок подтверждения потребности на следующий год. На счёте осталось 8 млн ₽, работы по одному контракту ещё не закончены. Бухгалтер считает остаток свободным ресурсом для новых расходов. Участник получает акт сверки, контракт и письмо получателя; решение касается дальнейшего использования целевых денег и оформления требуемых подтверждений."}, {"case_key": "bank-legal-2026-047", "title": "Склад агломерации", "situation": "В Ленинградской области муниципалитет хочет перенести чужую региональную стройку в свой бюджет, не получив передачи полномочий и источника финансирования.\n\nОбъект находится на территории муниципалитета, но заказчиком и носителем полномочия указан региональный орган. Местный совет готов включить стройку в свой перечень расходов уже сегодня. Регион не передал ни обязательство, ни финансовое обеспечение. Участник изучает договоры, реестр полномочий и проект бюджета; необходимо установить надлежащую процедуру взаимодействия уровней власти до появления нового расхода."}, {"case_key": "bank-legal-2026-048", "title": "Инвестор без прибыли", "situation": "В Липецкой области поддержку обещают за прирост рабочих мест. Фирма заменяет показатель занятости числом заключённых договоров услуг с подрядчиками.\n\nВ соглашении указаны новые рабочие места и сроки сохранения занятости. Компания представила 30 договоров услуг с внешними исполнителями вместо сведений о 30 новых работниках. При этом отчёт включает прежний штат как дополнительный результат проекта. Участнику доступны трудовые сведения и условия поддержки; необходимо определить, какой показатель подтверждён и как оценить выполнение соглашения."}, {"case_key": "bank-legal-2026-049", "title": "Золотой резерв", "situation": "Магаданская область хочет покрыть дефицит прогнозом добычи по лицензии, которую компания ещё не получила. Доход включён как гарантированный.\n\nПрогноз доходов рассчитывается по мощности будущего участка и максимальной цене металла. Компания ещё проходит процедуру получения права пользования недрами и не утвердила график добычи. В расходном плане уже назначены обязательства под весь прогнозируемый поток. Участник получает лицензирующее досье и несколько ценовых сценариев; задача — оценить подтверждённость предпосылок до утверждения источника покрытия дефицита."}, {"case_key": "bank-legal-2026-050", "title": "Кадастровое возражение", "situation": "В Московской области компания считает кадастровую стоимость ошибочной и полностью прекращает уплату налога, не используя процедуру оспаривания и перерасчёта.\n\nОрганизация получила отчёт оценщика с иной стоимостью и направила обращение о пересмотре. Решение компетентного органа по этому обращению ещё не принято, а срок платежа наступил. Бухгалтер исключил налог из платёжного календаря полностью. Участнику переданы действующие сведения, обращение и расчёт; необходимо определить порядок действий в период спора и условия последующего перерасчёта."}, {"case_key": "bank-legal-2026-051", "title": "Арктический подряд", "situation": "В Мурманской области цену долгосрочного контракта увеличивают письмом подрядчика из-за логистики. Основание изменения условий контракта не проверено.\n\nКонтракт предусматривает доставку материалов в несколько портов и фиксированную цену. Подрядчик приложил новые тарифы перевозчиков, но не указал норму и обстоятельство, допускающие изменение соглашения. Часть поставки уже выполнена по прежней цене. Участник получает контракт, график и расчёт логистики; необходимо определить порядок рассмотрения требования до оформления дополнительного соглашения."}, {"case_key": "bank-legal-2026-052", "title": "Компенсация депо", "situation": "В Нижегородской области перевозчику выплачивают компенсацию по неподтверждённой оценке выпадающих доходов. Методика расчёта отсутствует в акте.\n\nПеревозчик сравнивает фактическую выручку с максимальной загрузкой депо и объявляет всю разницу убытком. В расчёт включены направления, не относящиеся к льготному проезду. Финорган должен подготовить платёж на следующей неделе. Участнику переданы данные перевозок и проект акта; задача — проверить основание, границы и метод определения компенсируемого расхода."}, {"case_key": "bank-legal-2026-053", "title": "Новгородский аудит", "situation": "В Новгородской области внутренний финансовый аудит поручают тому же сотруднику, который единолично проводил проверяемые операции и должен оценить собственные ошибки.\n\nПроверяемый сотрудник самостоятельно составлял документы, подтверждал платежи и исправлял выявленные расхождения. Начальник считает, что он лучше всех знает материалы проверки. Отдельная функция оценки эффективности должна дать независимый вывод. Участник получил положение об аудите и перечень операций; необходимо выбрать состав и организацию проверки, сохранив возможность достоверно оценить результат."}, {"case_key": "bank-legal-2026-054", "title": "Научный аванс", "situation": "В Новосибирской области грант на исследования требует результатов и отчётности. Получатель просит заменить научный результат рекламным роликом без изменения соглашения.\n\nСоглашение предусматривает прототип, результаты испытаний и отчёт об использовании 5 млн ₽. Получатель подготовил красивую презентацию, но испытания не завершил. В ведомстве опасаются пропустить срок представления отчёта по программе. Участник изучает календарь, показатели и фактические материалы; необходимо определить, какое подтверждение результата допустимо и как рассмотреть просьбу об изменении условий."}, {"case_key": "bank-legal-2026-055", "title": "Омская концессия", "situation": "В Омской области концессионный объект хотят оплатить одновременно полностью из бюджета и через компенсацию тех же затрат инвестору по другому соглашению.\n\nВ финансовой модели одна и та же линия очистки включена в два источника полного возмещения. Инвестор показывает разные наименования затрат, однако заводской номер оборудования совпадает. Общая сумма поддержки превышает подтверждённую стоимость объекта. Участнику переданы соглашения и финансовая модель; важно проверить движение конкретных расходов до утверждения очередного перечисления."}, {"case_key": "bank-legal-2026-056", "title": "Газовый расчёт", "situation": "В Оренбургской области добывающая компания применяет нефтяной коэффициент к природному газу без проверки специальных правил расчёта НДПИ.\n\nВ добычном отчёте отдельно указаны газ, конденсат и нефть. Бухгалтер взял одну формулу из прежней декларации для всех видов сырья. Технический специалист предупреждает, что показатели добычи и характеристики участков различаются. Участник получает лицензионные сведения и расчёт; решение требует сопоставить каждый вид полезного ископаемого с применимым порядком определения налога."}, {"case_key": "bank-legal-2026-057", "title": "Орловский отбор", "situation": "В Орловской области заявка на субсидию подана в срок, но комиссия исключила её из-за устного указания перенести приём на день раньше.\n\nЭлектронная система сохранила время приёма заявки до опубликованного окончания отбора. Новая дата отсутствует на официальной странице и в нормативном порядке. Секретарь комиссии предлагает удалить запись как позднюю, чтобы не переделывать протокол. Участнику переданы извещение, подтверждение отправки и журнал заявок; необходимо определить дальнейшее рассмотрение и документирование решения."}, {"case_key": "bank-legal-2026-058", "title": "Пензенский лизинг", "situation": "В Пензенской области субсидия возмещает лизинговые платежи. В заявку включён выкуп объекта и штраф за просрочку, хотя эти затраты не названы допустимыми.\n\nЛизинговый график отделяет плату за пользование, выкупную стоимость и неустойку. Предприятие объединило три суммы в одну строку подтверждённых затрат на оборудование. В соглашении о поддержке описаны допустимые платежи и период возмещения. Участнику нужно сопоставить документы с этими условиями до расчёта субсидии, сохранив возможность объяснить каждое включение и исключение."}, {"case_key": "bank-legal-2026-059", "title": "Пермское соглашение", "situation": "В Пермском крае регион подписывает инвестиционное соглашение, обещая неизменность местного налога, ставку которого устанавливает муниципальный представительный орган.\n\nИнвестор рассчитывает окупаемость объекта на основании обещанной ставки земельного налога. Муниципальный совет ранее обсуждал её изменение, но не участвовал в подписании регионального соглашения. В письме предприятию обещаны компенсации при любом росте налога. Участник получил соглашение и местный акт; необходимо установить компетенцию участников и пределы принимаемых обязательств."}, {"case_key": "bank-legal-2026-060", "title": "Псковский мост", "situation": "В Псковской области мост принадлежит муниципалитету, а регион выделяет средства без определения вида межбюджетного трансферта, цели и условий.\n\nМестный совет подтвердил необходимость ремонта, однако ремонтный контракт ещё не заключён. Регион направляет 20 млн ₽ с формулировкой «на помощь району», без уточнения порядка использования и отчётности. В проекте местного бюджета расход пока не отражён. Участник получает документы собственности, смету и письмо финансиста; нужно определить правовую форму передачи денег до начала работ."}, {"case_key": "bank-legal-2026-061", "title": "Ростовская закупка", "situation": "В Ростовской области заказчик требует в конкурсе, чтобы участник был зарегистрирован только в этом регионе, хотя законного основания ограничения нет.\n\nПоставщики из соседних областей готовы выполнить условия поставки и обслуживания. Заказчик объясняет ограничение заботой о региональной занятости, но предмет закупки не связан с местом регистрации фирмы. Жалоба поступила до окончания приёма заявок. Участнику переданы извещение и проект документации; требуется определить действие до подведения итогов конкурса."}, {"case_key": "bank-legal-2026-062", "title": "Рязанская отчётность", "situation": "В Рязанской области общий отчёт об исполнении бюджета показывает планы вместо кассовых расходов. Пояснение о задержке платежей убрано перед слушаниями.\n\nВ публичной таблице указано 100% освоения по программе, хотя казначейские платежи составили 72% ассигнований. Оставшиеся деньги не ушли из-за непредставленных актов подрядчика. Доклад на слушаниях подготовлен по плановой ведомости. Участник должен сопоставить план, принятые обязательства и кассовое исполнение, чтобы определить корректные показатели отчёта и содержание пояснений."}, {"case_key": "bank-legal-2026-063", "title": "Самарский налоговый кредит", "situation": "В Самарской области организация просит инвестиционный налоговый кредит. Ей предлагают обычную беспроцентную субсидию, называя обе меры одинаковыми.\n\nЗаявитель предлагает модернизировать производство и приложил расчёт будущих платежей. Проект налогового кредита предусматривает срок, проценты и порядок возврата; проект субсидии — бюджетное перечисление с иными условиями. В служебной записке оба инструмента записаны одной суммой «помощи». Участнику нужно определить различия правовых последствий до выбора механизма и подготовки документов."}, {"case_key": "bank-legal-2026-064", "title": "Саратовский контракт", "situation": "В Саратовской области учреждение заключает контракт на будущий год, игнорируя ограничения принятия обязательств и наличие предусмотренного многолетнего основания.\n\nУчреждение хочет зарезервировать оборудование на 24 месяца и договориться о платежах в двух финансовых годах. Текущие лимиты покрывают только первую часть цены. В документах нет решения или иного применимого основания долгосрочного обязательства. Участник получает проект договора и бюджетные показатели; необходимо проверить возможность принятия всего обязательства до подписания."}, {"case_key": "bank-legal-2026-065", "title": "Сахалинская доля", "situation": "Сахалинская область рассчитывает доходы по проекту раздела продукции как по обычной системе НДПИ и налога на прибыль, не проверяя соглашение.\n\nВ соглашении предусмотрены особый порядок учёта продукции, компенсационные расходы и распределение долей. Финансист переносит в прогноз стандартный расчёт по другой добывающей компании. В результате один поток записан сразу в два вида поступлений. Участник получает текст соглашения и ведомость добычи; задача — установить применимую схему и проверить отсутствие двойного счёта доходов."}, {"case_key": "bank-legal-2026-066", "title": "Уральский залог", "situation": "В Свердловской области имущество казны хотят передать в залог по долгу частного предприятия одним служебным письмом без полномочий и оценки последствий.\n\nПредприятие просит залог склада казны для продления банковского кредита. Оценка объекта и перечень допустимых операций не приложены, а подписант письма не управляет этим имуществом. В случае взыскания регион потеряет используемый склад. Участнику переданы запрос банка и реестр собственности; требуется определить уполномоченное решение и оценку обязательств до предоставления обеспечения."}, {"case_key": "bank-legal-2026-067", "title": "Смоленское пожертвование", "situation": "В Смоленской области учреждению предлагают пожертвование с условием закупать товар только у жертвователя по завышенной цене. Условие противоречит цели и процедуре расходования.\n\nДоговор пожертвования предусматривает 2 млн ₽, но связывает использование денег с покупкой по указанной цене. Аналогичный товар другого поставщика стоит существенно дешевле. Учреждение считает, что без бюджетного источника закупочные требования не применяются. Участник изучает условия дара, режим учреждения и предложения рынка до принятия денег и обязательств по их расходованию."}, {"case_key": "bank-legal-2026-068", "title": "Тамбовский бюджет участия", "situation": "В Тамбовской области жители выбрали проект. Администрация подменила его другим объектом без информирования и предусмотренного пересмотра инициативного проекта.\n\nЖители выбрали освещение пешеходного маршрута и собрали подтверждения поддержки проекта. В новом плане администрации вместо него указана площадка у другого здания. Авторы инициативы узнали об изменении из объявления подрядчика. Участнику доступны протокол отбора и проект финансирования; необходимо определить порядок информирования и изменения решения до заключения контракта."}, {"case_key": "bank-legal-2026-069", "title": "Тверская гарантия", "situation": "В Тверской области гарантия уже выдана и учтена, но при расчёте долговых обязательств её исключают, потому что кредитор ещё не предъявил требование.\n\nГарантия содержит определённый объём ответственности и действует до погашения кредита. Предприятие пока исправно вносит платежи, поэтому финансист предлагает не учитывать риск в долговой книге. Новый заём рассчитывается по уменьшенному показателю нагрузки. Участник получает гарантию и расчёт предельного долга; нужно установить, как учитывать существующее обязательство до решения о заимствовании."}, {"case_key": "bank-legal-2026-070", "title": "Томская интеллектуальная собственность", "situation": "В Томской области университетский стартап просит бюджетную инвестицию. Организация не определила собственника прав на технологию и основания участия региона.\n\nПрототип создан преподавателями университета и сотрудниками компании по разным соглашениям. В заявке на участие региона указано будущее владение долей, но договоры об интеллектуальных правах не представлены. Оценка стоимости технологии основана на ожиданиях продаж. Участник изучает состав участников и документы прав; необходимо определить подтверждения для решения о бюджетном вложении."}, {"case_key": "bank-legal-2026-071", "title": "Тульская неустойка", "situation": "В Тульской области поставщик сорвал поставку оборудования. Заказчик прощает неустойку только из-за дружеского письма без предусмотренного законом основания.\n\nОборудование поступило на три недели позже срока, что подтверждается складским журналом. Поставщик сослался на давнее знакомство с руководителем и попросил закрыть вопрос письмом. Юрист не нашёл документов о законном освобождении или списании. Участник получает контракт и даты исполнения; решение касается надлежащего рассмотрения ответственности и фиксации основания выбранного действия."}, {"case_key": "bank-legal-2026-072", "title": "Тюменский знаменатель", "situation": "Тюменская область сводит собственные доходы с доходами автономных округов и публикует итог как доход именно областного бюджета, не консолидированного.\n\nНа слайде для публичного обсуждения отсутствует подпись о составе территории и бюджетов. Читатели сравнивают полученную сумму с доходами отдельного субъекта за прошлый год. В рабочей таблице сведения автономных округов выделены отдельно. Участник должен определить корректное название агрегата и расчёт, чтобы не смешивать областной бюджет с консолидированными показателями."}, {"case_key": "bank-legal-2026-073", "title": "Ульяновский самолёт", "situation": "В Ульяновской области авиапредприятию компенсируют затраты на оборудование. Приложенный акт относится к другому юридическому лицу группы.\n\nЗаявитель и владелец оборудования имеют разные идентификационные номера и отдельные договоры. Документ оплаты представлен дочерней организацией, а субсидию просит головная компания. В условиях программы возмещаются затраты конкретного получателя. Участник получает реестр группы и первичные документы; нужно проверить, чьи расходы подтверждены и какой пакет может быть принят."}, {"case_key": "bank-legal-2026-074", "title": "Челябинская реконструкция", "situation": "В Челябинской области проект реконструкции бюджетного объекта изменён так, что выросла стоимость. Получатель просит перечислить превышение без изменения бюджетного решения.\n\nПроектировщик добавил новый корпус и изменил технические решения после экспертизы. Подрядчик представил дополнительную смету на 16 млн ₽ сверх первоначального обеспечения. В казначейство направлена заявка по прежнему объекту и цене. Участнику переданы версии проекта и финансовое решение; необходимо определить последовательность оформления изменений до перечисления увеличенной суммы."}, {"case_key": "bank-legal-2026-075", "title": "Забайкальский ваучер", "situation": "В Забайкальском крае компенсацию проживания для работников предлагают обложить НДФЛ как зарплату без проверки установленной законом льготы и характера выплаты.\n\nРаботодатель оплатил жильё работникам по отдельной программе переезда и включил платежи в общий зарплатный регистр. В трудовых документах отражено основание предоставления жилья, но бухгалтер не проверил категорию выплаты. Работники запросили расчёт удержания. Участник сопоставляет документы программы, выплаты и применимые условия налогообложения до формирования отчётности."}, {"case_key": "bank-legal-2026-076", "title": "Ярославская территория", "situation": "В Ярославской области сбор за размещение вывески назван налогом и вводится письмом департамента. В НК такой налог не предусмотрен.\n\nПисьмо устанавливает ежемесячный платёж для всех владельцев вывесок без договора об услуге. В акте отсутствуют налоговая база, плательщики и законное основание нового налога. Предпринимателю угрожают отказом в согласовании вывески при неоплате. Участник получает письмо и документы размещения; необходимо определить природу требования и порядок действий по конкретному заявлению."}, {"case_key": "bank-legal-2026-077", "title": "Московский торговый объект", "situation": "В Москве предприниматель рассчитывает торговый сбор по площади всего здания, хотя использует отдельный объект торговли и должен учитывать конкретную категорию.\n\nТорговый зал занимает 80 м² в здании площадью 900 м², где есть офисы и склад другого арендатора. В расчёт перенесена площадь всей недвижимости из общей выписки. Вид и расположение торгового объекта подтверждены договором. Участник получает план помещений и сведения об использовании; требуется проверить выбранную категорию и соответствующие параметры расчёта сбора."}, {"case_key": "bank-legal-2026-078", "title": "Петербургский фасад", "situation": "В Санкт-Петербурге бюджетное финансирование реставрации предлагают выдать собственнику без обязательств по сохранению объекта культурного наследия и контролю результата.\n\nЗдание находится в частной собственности и включено в перечень охраняемых объектов. Смета предусматривает реставрацию фасада, но проект соглашения не определяет содержание результата и последующий контроль. Собственник намерен менять элементы декора по своему проекту. Участнику переданы охранные документы и смета; нужно оценить условия передачи денег и исполнения обязательств по сохранению объекта."}, {"case_key": "bank-legal-2026-079", "title": "Биробиджанское исполнение", "situation": "В Еврейской автономной области платёж оформляют на основании неподписанного акта выполненных работ. Получатель уверяет, что подпись появится после перечисления.\n\nПодрядчик приложил неподписанный акт и фотографии, часть которых относится к другому помещению. Ответственный за приёмку ещё не осмотрел выполненные работы. Бухгалтер готовит платёж, чтобы успеть до конца месяца. Участник получает контракт, акт и материалы осмотра; необходимо определить подтверждённость исполнения и дальнейшие документы до перечисления средств."}, {"case_key": "bank-legal-2026-080", "title": "Ненецкий норматив", "situation": "В Ненецком автономном округе местному бюджету обещают определённую долю дохода, но не оформляют предусмотренный акт о дополнительном нормативе отчисления.\n\nВ бюджетном проекте поселения доля налога включена как уже действующий норматив. Региональный представитель обсуждал её на совещании, но акт не опубликован. Объём расходов сформирован под ожидаемый доход. Участник изучает действующие нормативы и протокол совещания; нужно определить правовое основание изменения и корректный момент отражения поступления в плане."}, {"case_key": "bank-legal-2026-081", "title": "Югорское соглашение", "situation": "В Югре соглашение о субсидии подписано. Сотрудник позже требует новые обязательства получателя, которых нет в соглашении и нормативном порядке.\n\nПолучатель выполняет согласованные показатели и представил промежуточный отчёт. В новом письме ведомство добавило требования к числу работников, которых не было при заключении соглашения. За отказ обещают приостановить платёж. Участник получает обе версии условий и документы отбора; требуется оценить допустимость изменения и порядок рассмотрения позиции получателя."}, {"case_key": "bank-legal-2026-082", "title": "Чукотский северный завоз", "situation": "На Чукотке средства на северный завоз предлагается перечислить организации без проверки включения расходов в план завоза и подтверждения поставки.\n\nПоставка должна пройти по отдельному календарю до закрытия навигации. В заявке объединены основные товары завоза и коммерческая партия оборудования, не включённая в утверждённый план. Накладные подтверждают только часть груза. Участник изучает план, договор и перевозочные документы; нужно установить объём допустимого финансирования и необходимые подтверждения до платежа."}, {"case_key": "bank-legal-2026-083", "title": "Ямальский платёж", "situation": "На Ямале имущество получателя субсидии арестовано, но он просит перечислить деньги на счёт другой фирмы, не указанной в соглашении.\n\nВ соглашении определены конкретный получатель и его обязанности по отчёту. Новая фирма предлагает принять деньги и рассчитаться с подрядчиком, но не входит в договорные отношения. Получатель объясняет смену счёта исполнительными ограничениями. Участнику переданы реквизиты, соглашение и сведения об ограничении; необходимо определить допустимость перечисления и предусмотренный порядок дальнейших действий."}, {"case_key": "bank-legal-2026-084", "title": "Крымский гостиничный реестр", "situation": "В Республике Крым объект размещения не внесён в надлежащий реестр. Муниципалитет автоматически считает отсутствие записи освобождением от любого налогового обязательства.\n\nГостиница фактически размещает гостей и отражает доходы, а заявка на включение в реестр находится на рассмотрении. В служебной записке смешаны условия конкретного налога и отсутствие любых обязанностей бизнеса. Администратор просит отменить все расчёты. Участник получает документы объекта, период деятельности и налоговые регистры; необходимо отдельно проверить применимость каждого обязательства."}, {"case_key": "bank-legal-2026-085", "title": "Севастопольская земля", "situation": "В Севастополе участок передан организации в безвозмездное пользование. Бухгалтер начисляет земельный налог как при собственности без проверки объекта и плательщика.\n\nДоговор устанавливает срок пользования и порядок возврата участка без передачи собственности. Выписка подтверждает другого собственника, а налоговый расчёт составлен по общей карточке имущества организации. Бухгалтеру требуется ответ до платежа. Участник получает договор и выписку; нужно установить статус пользователя и применимые условия признания плательщиком, а не исходить из самого факта нахождения на земле."}, {"case_key": "bank-legal-2026-086", "title": "Донецкая восстановительная смета", "situation": "Для учебного сценария Донецкой Народной Республики выделена целевая помощь на восстановление водоснабжения. Смета включает мебель администрации, не связанную с проектом.\n\nВ учебном соглашении определены насосная станция, трубы и контроль восстановления подачи воды. Позиция о мебели появилась в последней версии сметы без изменения цели помощи. На неё предусмотрено 1,2 млн ₽. Участник сравнивает версии сметы и перечень результатов; необходимо проверить связь конкретной затраты с соглашением до утверждения финансирования."}, {"case_key": "bank-legal-2026-087", "title": "Луганский переходный учёт", "situation": "В учебном сценарии Луганской Народной Республики организация применяет обычную налоговую норму, не проверив предусмотренное переходное регулирование по периоду и статусу.\n\nВ досье отражены дата регистрации организации, период операции и начало применения отдельных норм. Бухгалтер скопировал расчёт компании из другого субъекта, не учитывая эти даты. Документы о статусе получены до сдачи отчётности. Участник сопоставляет период, территориальные правила и конкретную операцию; выбор должен опираться на действующее для этого случая регулирование."}, {"case_key": "bank-legal-2026-088", "title": "Херсонская субвенция", "situation": "В учебном сценарии Херсонской области переданное государственное полномочие расширяют, но размер субвенции и норматив затрат не пересматривают.\n\nОрган получает дополнительные заявления по расширенному перечню услуг, но финансирование рассчитано на прежний объём. Исполнители предлагают сократить сроки других обязательных работ, чтобы уложиться в сумму. В проекте передачи полномочия отсутствует новый расчёт затрат. Участник получает перечень функций и норматив расходов; необходимо определить порядок финансового обеспечения изменённого объёма."}, {"case_key": "bank-legal-2026-089", "title": "Запорожская стройка", "situation": "В учебном сценарии Запорожской области финансируют восстановление объекта, не установив собственника, получателя и законное основание бюджетной инвестиции.\n\nВосстанавливаемый объект числится в нескольких старых реестрах с различными сведениями о владельце. Организация предлагает принять средства как будущий оператор, но её права не оформлены. Проект предусматривает капитальные вложения, а не текущую услугу. Участнику переданы выписки и смета; необходимо установить законного получателя, объект и основание вложения до принятия обязательства."}, {"case_key": "bank-legal-2026-090", "title": "Обратная сила взыскания", "situation": "Ведомство увеличило административный штраф после совершения нарушения. Инспектор применяет новую, более высокую сумму к старому эпизоду. Дело ещё не рассмотрено.\n\nНарушение зафиксировано 18 марта, а новая редакция нормы вступила в силу 1 апреля. В старой редакции штраф составлял 10 тыс. ₽, в новой — 25 тыс. ₽. Рассмотрение назначено на 8 апреля; инспектор приложил обе редакции к протоколу. Участнику нужно выбрать основание решения с учётом времени совершения деяния и характера изменения ответственности."}, {"case_key": "bank-legal-2026-091", "title": "Письмо вместо нормативного акта", "situation": "Министерство разослало письмо с обязательным сбором за разрешение. Закон не предусматривает сбор, письмо не прошло предусмотренную для нормативных актов процедуру. Заявителю отказали без квитанции.\n\nПисьмо разослано территориальным подразделениям и помещено в разделе новостей министерства. Заявитель подготовил полный установленный комплект, но сотрудник требует ещё квитанцию на 3 тыс. ₽. В письме отсутствуют реквизиты принятия нормативного акта, а сумма не указана в законе. Участник получает заявление, перечень документов и письмо; нужно решить, как организовать приём."}, {"case_key": "bank-legal-2026-092", "title": "Закон без опубликования", "situation": "Парламент принял закон, но его официальное опубликование не состоялось. Орган контроля уже требует от жителей исполнять новую обязанность, затрагивающую их права.\n\nПредприятие узнало о новом требовании из трансляции заседания, а официального текста в доступном источнике пока нет. Контролёр требует начать исполнение уже завтра и грозит санкцией за прошлую неделю. Секретарь показывает подписанную копию и дату принятия. Участнику предстоит сопоставить принятие, опубликование, вступление в силу и доступность обязанности для адресатов."}, {"case_key": "bank-legal-2026-093", "title": "Два чтения вместо трёх", "situation": "Законопроект внесён в Государственную Думу. Комитет хочет заменить третье чтение публикацией пресс-релиза и направить текст дальше, поскольку принципиальные поправки уже обсуждены.\n\nКо второму чтению появились поправки к двум статьям, а окончательный текст ещё не сверен. Председательствующий предлагает провести пресс-конференцию и объявить закон принятым. В повестке третье чтение отсутствует, некоторые депутаты просят сначала проверить текст. Участник распоряжается проектом, таблицей поправок и протоколом предыдущего голосования; решение требуется до объявления результата."}, {"case_key": "bank-legal-2026-094", "title": "Заключение на расходный закон", "situation": "Депутаты предложили новую выплату из федерального бюджета и хотят немедленно внести законопроект. Заключения Правительства на проект нет.\n\nГруппа депутатов подготовила ежемесячную выплату новой категории граждан с расходом 6 млрд ₽ в год. К инициативе приложены пояснительная записка и расчёт, но заключения Правительства нет. Авторы считают расчёт достаточной заменой и просят включить проект в повестку. Участник должен определить дальнейшее движение пакета до начала рассмотрения."}, {"case_key": "bank-legal-2026-095", "title": "Возвращение закона с возражениями", "situation": "Президент отклонил федеральный закон и вернул его в парламент с возражениями. Думская фракция собирается преодолеть отклонение простым большинством, а Совет Федерации не приглашать.\n\nПрезидент направил мотивированные возражения к двум статьям, а закон вернулся в Государственную Думу. На заседании собрано обычное большинство, голосование в Совете Федерации не проводилось. Сторонники проекта предлагают сразу передать первоначальный текст на подпись. Участнику доступны письмо Президента и результаты голосования; необходимо выбрать дальнейшую процедуру."}, {"case_key": "bank-legal-2026-096", "title": "Проверка конституционности до подписи", "situation": "Принятый закон вызывает конституционные сомнения. Президент намерен обратиться в Конституционный Суд до подписания, а секретариат считает, что срок подписи нельзя приостанавливать.\n\nЗакон поступил Президенту вместе с замечаниями о возможном противоречии Конституции. Обращение в Конституционный Суд направлено до подписания, его принятие подтверждено канцелярией. В календаре секретариата продолжает идти обычный срок подписания без отдельной отметки. Участник получает закон, обращение и календарь; нужно определить действие до истечения указанной даты."}, {"case_key": "bank-legal-2026-097", "title": "Правительство и поручение партии", "situation": "Партийное руководство направило министру обязательное, по его мнению, поручение распределить субсидии только между муниципалитетами, где партия получила большинство.\n\nВ проекте распределения помощи указаны пять муниципалитетов, победивших на партийном голосовании. У остальных территорий есть подтверждённые потребности, но их заявки предлагают отложить. Министру переданы партийное поручение, проект отбора и бюджетная строка поддержки. Решение требуется перед утверждением критериев, когда деньги ещё не перечислены."}, {"case_key": "bank-legal-2026-098", "title": "Устав без обязательных положений", "situation": "Учредители партии представили красивую программу, но в уставе нет порядка вступления, прекращения членства и компетенции руководящих органов. Они просят зарегистрировать партию по её политической программе.\n\nПартия представила программу, протокол съезда, список учредителей и красиво оформленный устав. В уставе описаны цели, но невозможно определить порядок приёма и выхода членов или полномочия руководящих органов. Заявитель просит регистрацию до начала агитационной кампании. Участник должен оценить комплект и подготовить адресный ответ по обнаруженным пробелам."}, {"case_key": "bank-legal-2026-099", "title": "Отказ из-за политической позиции", "situation": "Регистрационный орган собирается отказать партии только потому, что её программа критикует действующее руководство. Документы отвечают формальным требованиям, запрещённых целей не заявлено.\n\nРегистрационное досье содержит обязательные сведения и документы, замечаний к оформлению не выявлено. В проекте отказа указано лишь, что программа партии резко критикует действующую администрацию. Заявитель просит показать конкретное основание отказа. Участнику доступны досье и проект письма; решение требуется до отправки официального ответа."}, {"case_key": "bank-legal-2026-100", "title": "Неотмеченная агитация", "situation": "Редакция разместила оплаченный кандидатом материал без сведений об оплате из избирательного фонда. Штаб считает, что достаточно отметить публикацию словом «новость».\n\nРедакция получила оплату из фонда кандидата и выпустила материал с призывом голосовать за него. В публикации не указано финансирование, а в журнале редакции она записана как обычная новость. Конкурент сохранил выпуск и платёжные сведения. Участнику нужно квалифицировать материал и выбрать действие до повторного выхода рекламы."}, {"case_key": "bank-legal-2026-101", "title": "Один бюллетень за соседа", "situation": "Член комиссии выдаёт избирателю дополнительный бюллетень за соседа после предъявления фотографии его паспорта. Сосед на участок не пришёл.\n\nНа участке осталось достаточно бюллетеней, а очередь небольшая. Избиратель говорит, что сосед болен, и показывает фотографию его паспорта в телефоне. Доверенности, личного присутствия соседа и заявления о предусмотренной законом форме голосования нет. Участнику переданы список избирателей и журнал выдачи; решение нужно принять до выдачи второго бюллетеня."}, {"case_key": "bank-legal-2026-102", "title": "Победитель с конфликтом интересов", "situation": "Руководитель закупочной комиссии узнал, что участником конкурса стала компания его супруги. Он решил просто не выступать на заседании, сохранив голос.\n\nЗаявки ещё оцениваются, итоговый протокол не подписан. Компания супруги руководителя предлагает цену на 2% ниже конкурента, но по качеству оценки расходятся. Руководитель сообщил секретарю о родстве и попросил только не давать ему слово. Участник должен определить порядок действий комиссии до выставления окончательных баллов."}, {"case_key": "bank-legal-2026-103", "title": "Дробление единой закупки", "situation": "Учреждение разбило одну заранее известную потребность на множество малых договоров с тем же поставщиком, чтобы не проводить конкурентную процедуру.\n\nГодовой план учреждения содержит единую потребность в 120 компьютерах для одного корпуса. Проект предлагает двадцать договоров по шесть устройств с одинаковыми характеристиками и сроком доставки. Все договоры подготовлены для одного поставщика в одну неделю. Участнику доступны план и проекты договоров; необходимо выбрать способ оформления закупки до подписания."}, {"case_key": "bank-legal-2026-104", "title": "Техническое задание под марку", "situation": "Заказчик описал характеристики оборудования так, что им соответствует только один бренд. Потребность в именно этой марке не обоснована, эквиваленты запрещены.\n\nВ техническом задании повторены уникальные размеры и закрытый интерфейс одной модели оборудования. Специалист объясняет выбор привычкой сотрудников, но не представил расчёт совместимости или иной объективной необходимости. Два поставщика запросили допуск эквивалентов. Участник рассматривает проект извещения до публикации на площадке."}, {"case_key": "bank-legal-2026-105", "title": "Приёмка того, чего нет", "situation": "Поставщик просит подписать акт до поставки, чтобы закрыть год. На складе нет товара; он обещает доставить его после праздников.\n\nКонтракт предусматривает поставку 30 комплектов оборудования, а оплачивать можно после подтверждённой приёмки. Поставщик прислал подписанный со своей стороны акт и обещает привезти товар через две недели. Кладовщик письменно подтвердил отсутствие комплектов на складе. Участник должен решить, какой документ и какое действие допустимы перед закрытием отчётного периода."}, {"case_key": "bank-legal-2026-106", "title": "Жалоба на закупку после договора", "situation": "Участник оспаривает действия заказчика, но срок административного обжалования истёк и контракт заключён. Он просит комиссию отменить договор обычным письмом.\n\nЖалоба поступила после установленного срока административного рассмотрения, а поставщик уже приступил к исполнению контракта. Заявитель приложил переписку и просит вернуть процедуру на этап подачи заявок. Комиссия подготовила черновик письма об отмене договора. Участник получает даты, контракт и жалобу; необходимо определить доступный способ защиты и полномочия органа."}, {"case_key": "bank-legal-2026-107", "title": "Подпись под чужим полномочием", "situation": "Сотрудник администрации подписал договор от имени муниципалитета, хотя доверенности и полномочий по должности у него нет. Контрагент уже начал исполнение.\n\nПо положению договоры подписывает глава администрации или лицо с выданной доверенностью. Специалист подписал документ во время отпуска руководителя, не получив замещения или доверенности. Подрядчик уже выполнил подготовительные работы и направил счёт. Участнику нужно оценить возникшие последствия и оформить дальнейшие действия, не скрывая обстоятельства подписания."}, {"case_key": "bank-legal-2026-108", "title": "Молчание как новая аренда", "situation": "Арендатор государственного помещения продолжает пользоваться им после окончания договора. Арендодатель не возражает, но управляющий объявляет это автоматической продажей помещения.\n\nПосле окончания срока аренды организация продолжает платить ту же арендную плату. Собственник получает деньги и не направлял возражений против использования помещения. Управляющий предлагает выдать арендатору свидетельство о собственности вместо нового договора. Участнику доступны прежний договор, платежи и переписка; требуется определить действительное содержание отношений."}, {"case_key": "bank-legal-2026-109", "title": "Неустойка за каждый день", "situation": "Подрядчик нарушил срок на десять дней. Договор предусматривает ежедневную пеню, но заказчик одновременно считает её и после фактического исполнения за тот же период.\n\nПоставка должна была завершиться 5 июня, фактически завершилась 15 июня. Заказчик рассчитывает ежедневную пеню до 25 июня, хотя акт исполнения подписан 15 июня без спора о дате. Подрядчик согласен обсуждать десять дней просрочки и просит расчёт по дням. Участнику необходимо проверить период начисления и содержание требования."}, {"case_key": "bank-legal-2026-110", "title": "Отказ от гарантийного ремонта", "situation": "Покупатель обнаружил производственный дефект товара в гарантийный период. Продавец требует оплатить экспертизу заранее и отказывается принимать претензию без заводской коробки.\n\nПокупатель принёс неисправный ноутбук через четыре месяца после покупки с чеком и гарантийными документами. Следов неправильного использования продавец пока не установил. Приёмщик требует 4 тыс. ₽ за экспертизу и оригинальную упаковку, которой у покупателя нет. Участник рассматривает претензию до отказа в её регистрации."}, {"case_key": "bank-legal-2026-111", "title": "Цифровая подписка после отказа", "situation": "Потребитель прекратил онлайн-подписку, но сервис продолжает списывать деньги за новые периоды. В интерфейсе кнопка отказа существует, однако заявление не учитывается.\n\nПользователь отменил автопродление 12 мая и получил подтверждение на электронную почту. В июне и июле сервис списал ещё по 900 ₽ и показал активную подписку в кабинете. Поддержка ссылается на отсутствие бумажного заявления, хотя отказ оформлен предусмотренной кнопкой. Участнику переданы условия сервиса, подтверждение и выписка; нужно оценить требование о возврате."}, {"case_key": "bank-legal-2026-112", "title": "Больничный и увольнение", "situation": "Работодатель издал приказ об увольнении по своей инициативе в день временной нетрудоспособности сотрудника. Ликвидации организации нет.\n\nСотрудник находится на подтверждённом больничном, электронный листок доступен работодателю. Приказ мотивирован сокращением, а организация продолжает деятельность. В кадровом журнале предложена дата увольнения внутри периода нетрудоспособности. Участник должен проверить дату и основание перед выдачей документов и окончательным расчётом."}, {"case_key": "bank-legal-2026-113", "title": "Испытание для беременной", "situation": "При приёме беременной сотрудницы включили в договор испытательный срок. После отрицательного результата начальник собирается прекратить договор как не прошедшей испытание.\n\nСотрудница сообщила о беременности и представила медицинский документ до приёма на работу. В типовой договор автоматически включили трёхмесячное испытание. Через месяц руководитель составил отрицательную оценку и подготовил уведомление о прекращении договора. Участнику переданы договор, документ и оценка; необходимо решить вопрос до вручения уведомления."}, {"case_key": "bank-legal-2026-114", "title": "Отпуск вместо задолженности", "situation": "Работнику не выплатили зарплату два месяца. Бухгалтерия предлагает зачесть задолженность ежегодным отпуском без отпускных и без согласования.\n\nЗадолженность составляет 86 тыс. ₽, даты начислений подтверждены расчётными листками. Работник не просил отпуск и намерен продолжать работу. Бухгалтер предлагает подписать задним числом заявление и считать долг погашенным днями отдыха. Участник должен оценить предложенное оформление и выбрать действие по существующей задолженности."}, {"case_key": "bank-legal-2026-115", "title": "Обязательная сверхурочная смена", "situation": "Руководитель назначил сверхурочную работу родителю ребёнка до трёх лет без письменного согласия и без ознакомления с правом отказаться. Исключительной ситуации нет.\n\nПроизводственный заказ можно выполнить в течение следующей недели, угрозы аварии или чрезвычайного обстоятельства нет. Работнику с двухлетним ребёнком назначили дополнительную смену сообщением в рабочем чате. Письменное согласие и уведомление о праве отказаться отсутствуют. Участник получает график и сообщение; нужно решить, как оформить работу до начала смены."}, {"case_key": "bank-legal-2026-116", "title": "Публичный список диагнозов", "situation": "Учреждение вывесило в открытом коридоре имена пациентов с диагнозами, объясняя это удобством приёма. Согласий на такое раскрытие нет.\n\nНа доске у регистратуры указаны фамилии, время приёма и диагнозы двадцати пациентов. Коридор открыт для сопровождающих и посетителей других отделений. Один пациент просит убрать сведения, администратор ссылается на удобство очереди. Участник должен оценить объём раскрытия и организовать запись пациентов с учётом обращения."}, {"case_key": "bank-legal-2026-117", "title": "Паспорт на личную почту", "situation": "Служащий отправил сканы паспортов заявителей на свою личную почту для работы дома. Разрешённого защищённого канала и установленного основания такой передачи нет.\n\nДля подготовки отчёта служащий скачал сканы двенадцати паспортов из ведомственной системы. Личный почтовый сервис хранит вложения за пределами разрешённого рабочего контура. Руководитель узнал о передаче до публикации отчёта, доступ к письму пока не ограничен. Участнику доступны журнал выгрузки и служебное объяснение; нужно выбрать действия по инциденту."}, {"case_key": "bank-legal-2026-118", "title": "Камера с распознаванием лиц", "situation": "Муниципальное учреждение вводит идентификацию посетителей по лицу. Оно считает, что таблички «ведётся видеонаблюдение» достаточно для любых биометрических процедур.\n\nТурникет сопоставляет изображение лица посетителя с заранее созданным профилем и сохраняет результат идентификации. Альтернативный способ входа не предусмотрен, а посетители увидели только общую табличку о видеонаблюдении. Учреждение ещё не утвердило отдельный порядок обработки этих данных. Участник оценивает запуск системы до её обязательного использования."}, {"case_key": "bank-legal-2026-119", "title": "Ответ на обращение без сути", "situation": "Житель указал конкретную неисправность и просит информацию о сроке ремонта. Орган прислал общую рекламу своей работы, не рассмотрев поставленный вопрос.\n\nВ обращении указаны адрес аварийного участка, даты предыдущих заявок и просьба сообщить план ремонта. Ответ содержит фотографии благоустройства другого квартала и общую благодарность за активность. Срок ответа подошёл к концу, заявитель уточняет, рассмотрены ли его вопросы. Участнику переданы оба текста; нужно определить содержание дальнейшего ответа."}, {"case_key": "bank-legal-2026-120", "title": "Тайна вместо открытого бюджета", "situation": "Орган отказывает в доступе к опубликованным бюджетным данным, объявив весь свой бюджет служебной тайной. Ограничение законом не обосновано.\n\nЗапрошены утверждённые доходы, расходы и пояснения к опубликованному бюджету. Эти материалы уже размещались на сайте совета, но после обновления раздела ссылки перестали открываться. В отказе отсутствует ссылка на конкретное ограничение доступа. Участник должен решить, как обработать запрос и восстановить доступ к соответствующим материалам."}, {"case_key": "bank-legal-2026-121", "title": "Согласование мирного собрания", "situation": "Орган получил уведомление о публичном мероприятии и вместо предусмотренной процедуры потребовал разрешение партийного руководства. Законного основания такого документа нет.\n\nОрганизаторы подали уведомление в установленный срок с маршрутом и предполагаемым числом участников. Администрация не направила мотивированного предложения по месту, а запросила согласие местного партийного руководителя. Срок ответа на уведомление истекает завтра. Участнику доступны уведомление и проект требования; необходимо выбрать дальнейшее действие органа."}, {"case_key": "bank-legal-2026-122", "title": "Отсутствие состава нарушения", "situation": "Контрольный орган доказал факт хозяйственной деятельности, но не установил обязательный признак административного состава. Он предлагает назначить штраф для профилактики.\n\nВ материалах есть фотографии и договор, подтверждающие работу предприятия. Для вменённого состава необходимо дополнительное обстоятельство, которого проверка не установила. Инспектор предлагает компенсировать этот пробел ссылкой на общественную опасность деятельности. Участник оценивает доказательства перед вынесением постановления."}, {"case_key": "bank-legal-2026-123", "title": "Протокол без извещения", "situation": "Орган составил протокол и рассмотрел дело без надлежащего извещения лица. Доказательств извещения нет, исключительные основания не установлены.\n\nУведомление отправили на старый адрес, хотя новый адрес указан в материалах проверки. Почтовое сообщение вернулось, иных подтверждений извещения нет. Дело рассмотрели в отсутствие лица, после чего ему направили только итоговое постановление. Участнику нужно оценить соблюдение процедуры и дальнейшее движение дела."}, {"case_key": "bank-legal-2026-124", "title": "Налог по ведомственной памятке", "situation": "Инспекция требует доплатить налог по ставке из памятки, которая расходится с применимым законом. Налогоплательщик представил расчёт по НК РФ.\n\nВ применимой редакции закона указана ставка 2%, а в памятке на стойке инспекции — 3%. Организация представила налоговый расчёт и копию действующей нормы за соответствующий период. Инспектор требует доплату, ссылаясь на одинаковую памятку во всех отделениях. Участник проверяет нормативное основание перед подготовкой требования."}, {"case_key": "bank-legal-2026-125", "title": "Излишне взысканный налог", "situation": "Со счёта организации взыскали сумму, затем отменённую решением по спору. Бухгалтерия инспекции предлагает засчитать её в неопределённые будущие платежи без установленной процедуры.\n\nПо результатам рассмотрения спора взыскание 480 тыс. ₽ признано необоснованным. Деньги уже списаны со счёта, организация представила решение и реквизиты. В проекте ответа отсутствуют срок, расчёт и указание применимой процедуры; предложено ждать будущей налоговой обязанности. Участнику нужно выбрать действие, учитывающее состояние расчётов и содержание отмены."}, {"case_key": "bank-legal-2026-126", "title": "Льгота за партийный билет", "situation": "Муниципальный совет хочет освободить от земельного налога только членов одной партии. Экономическое или социальное основание категории не объяснено.\n\nПроект льготы охватывает партийные земельные участки независимо от назначения и стоимости. Владельцы аналогичных участков без партийного членства остаются плательщиками. Пояснительная записка содержит только обещание поддержки сторонникам. Участник рассматривает проект муниципального акта до голосования и должен оценить основание выделенной категории."}, {"case_key": "bank-legal-2026-127", "title": "Региональный запрет торговли", "situation": "Региональное министерство письмом полностью запретило продажу законно обращающегося товара на территории субъекта, не имея законного полномочия на такой запрет.\n\nТовар разрешён к обороту при соблюдении федеральных требований, нарушений этих требований проверка не установила. Министерство направило торговым сетям письмо с требованием убрать его за три дня. В письме нет ссылки на предоставленное законом полномочие вводить такой запрет. Участнику нужно выбрать действие по письму и обращениям продавцов."}, {"case_key": "bank-legal-2026-128", "title": "Конкурентная аренда земли", "situation": "Администрация хочет без предусмотренного основания передать публичный участок знакомому предпринимателю. Другие желающие предложили участвовать в открытой процедуре.\n\nНа участок претендуют три предпринимателя, все предлагают допустимое использование. Знакомый администрации заявитель просит прямую аренду по письму поддержки, специальных оснований для этого в досье нет. Проект договора подготовлен до проверки способа предоставления. Участник получает кадастровые сведения и заявки; решение требуется перед отправкой договора."}, {"case_key": "bank-legal-2026-129", "title": "Стройка на территории памятника", "situation": "Застройщик начал земляные работы в охранной зоне объекта культурного наследия без необходимого согласования. Муниципалитет обещает узаконить всё актом приёмки здания.\n\nЭкскаватор начал земляные работы в границах охранной зоны, которые нанесены на официальную схему. У застройщика есть общий строительный пакет, но необходимое согласование для этой территории не представлено. Письмо муниципалитета обещает оформить результаты после завершения здания. Участник оценивает начало работ и полномочия предложенного подписанта."}, {"case_key": "bank-legal-2026-130", "title": "Экологический платёж вместо разрешения", "situation": "Предприятие утверждает, что уплата экологического платежа позволяет ему нарушать установленные условия выбросов. Условия разрешительной документации не соблюдены.\n\nВ отчёте предприятия указаны фактические выбросы выше согласованных условий. Платёж перечислен, и бухгалтер приложил квитанцию как объяснение продолжения работы без изменений. Экологический специалист отдельно составил акт о несоблюдении условий. Участнику переданы разрешительная документация, отчёт и платёж; необходимо определить значение каждого документа."}, {"case_key": "bank-legal-2026-131", "title": "Доступ к правосудию через начальника", "situation": "Канцелярия суда отказывает в приёме обращения, пока заявитель не получит согласие руководителя учреждения, чьи действия он оспаривает.\n\nЗаявитель оспаривает отказ учреждения, подписанный его руководителем. В канцелярии требуют разрешение этого же руководителя на обращение в суд. Форма заявления и приложенные документы отвечают установленным требованиям приёма. Участник рассматривает действия канцелярии до истечения срока обращения заявителя."}, {"case_key": "bank-legal-2026-132", "title": "Доказательство из слухов", "situation": "Орган основывает неблагоприятное решение только на анонимном пересказе. Проверяемых обстоятельств и иных доказательств нет, заявителю не дали представить объяснения.\n\nАнонимное сообщение содержит обвинение, но не указывает проверяемые даты, документы или свидетелей. Неблагоприятное решение готовят без ознакомления адресата с материалами. В досье нет дополнительных результатов проверки. Участнику необходимо оценить, какие факты установлены и какое решение возможно на представленном основании."}, {"case_key": "bank-legal-2026-133", "title": "Обязательное примирение без согласия", "situation": "Посредник обещает завершить спор медиацией и подписывает соглашение за стороны, которые не выражали согласия на его условия.\n\nСтороны обсуждали медиацию, но одна из них отклонила предложенную сумму выплаты. Посредник направил им подписанное только им соглашение и объявил спор завершённым. Полномочий подписывать за стороны ему не выдавали. Участник получает переписку и документ; нужно оценить его значение для дальнейшего урегулирования."}, {"case_key": "bank-legal-2026-134", "title": "Срок обращения и уважительная причина", "situation": "Заявитель пропустил процессуальный срок из-за подтверждённой длительной госпитализации. Секретарь предлагает навсегда закрыть доступ без рассмотрения ходатайства.\n\nГоспитализация длилась 35 дней и полностью охватывала заключительный период срока обращения. Заявитель приложил медицинские документы и ходатайство о восстановлении срока. Канцелярия предлагает вернуть весь комплект без передачи судье. Участник должен определить движение заявления и ходатайства с учётом документированных обстоятельств."}, {"case_key": "bank-legal-2026-135", "title": "Банкротство и один любимый кредитор", "situation": "Руководитель неплатёжеспособного предприятия выводит оставшиеся средства на погашение долга аффилированной компании, оставляя остальных кредиторов без имущества.\n\nНа счёте предприятия осталось 3 млн ₽ при обязательствах перед несколькими кредиторами на 11 млн ₽. Руководитель подготовил платёж аффилированной компании, срок требования которой не имеет очевидного преимущества. Остальные кредиторы уже направили требования, процедура несостоятельности обсуждается. Участник оценивает платёж до списания последнего доступного имущества."}, {"case_key": "bank-legal-2026-136", "title": "Наследство и неподписанное обещание", "situation": "После смерти владельца родственник предъявил переписку «квартира будет твоей» и требует оформить всё имущество в обход остальных наследников.\n\nВ переписке владелец обсуждал намерение передать квартиру родственнику, но отдельного оформленного распоряжения в досье нет. После смерти обнаружены также другие наследники и сведения об имуществе. Родственник просит оформить право немедленно, не уведомляя остальных. Участник рассматривает представленные материалы в рамках открытия наследственного дела."}, {"case_key": "bank-legal-2026-137", "title": "Договор с несовершеннолетним", "situation": "Магазин продал пятнадцатилетнему дорогую технику в кредит без необходимого согласия законного представителя. Продавец считает любой договор ребёнка безусловно действительным.\n\nСтоимость покупки составляет 110 тыс. ₽, оплата оформлена как обязательство на двенадцать месяцев. У продавца есть возраст покупателя, но отсутствуют документы о требуемом согласии или полной дееспособности. Законный представитель узнал о договоре после первого платёжного уведомления. Участник должен оценить характер сделки и заявленные последствия."}, {"case_key": "bank-legal-2026-138", "title": "Благоустройство без слушаний", "situation": "Администрация меняет документ территориального планирования, для которого предусмотрена публичная процедура. Она заменила её опросом подписчиков в своём канале.\n\nИзменение предусматривает размещение объекта рядом с жилым кварталом и затрагивает несколько участков. В электронном опросе участвовали подписчики канала, часть жителей о нём не знала. Официальные материалы публичной процедуры и протокол обсуждения не подготовлены. Участник рассматривает проект изменения до его утверждения представительным органом."}, {"case_key": "bank-legal-2026-139", "title": "Публичное обещание компенсации", "situation": "Пресс-секретарь обещал всем жителям компенсацию без утверждённого порядка и бюджетного основания. Социальная служба получила массовые заявления.\n\nПосле выступления пресс-секретаря поступило 240 заявлений о выплате по 20 тыс. ₽. В бюджете нет соответствующего основания, условия и круг получателей не утверждены. Сотрудники социальной службы предлагают начать платежи по записи трансляции. Участнику доступны обещание, заявления и бюджет; нужно организовать официальный ответ и дальнейшие действия."}, {"case_key": "bank-legal-2026-140", "title": "Национальность как основание отказа", "situation": "Муниципальное предприятие отказывает в обычной услуге исключительно из-за национальности клиента, хотя необходимые документы и основания имеются.\n\nКлиент представил тот же комплект документов, который принимают у остальных заявителей услуги. Сотрудник письменно указал единственной причиной отказа национальность клиента. Специального правового основания ограничения в досье нет. Участник рассматривает жалобу и условия оказания услуги перед направлением официального ответа."}, {"case_key": "bank-legal-2026-141", "title": "Личная переписка для служебного отчёта", "situation": "Руководитель публикует личную переписку сотрудника в открытом отчёте, объясняя это интересом аудитории. Согласия и законного основания раскрытия нет.\n\nПереписка получена из личного аккаунта и касается семейных обстоятельств сотрудника. Руководитель вставил скриншоты в проект открытого отчёта без согласия и указания законного основания. Отчёт ещё не опубликован, но доступен редактору сайта. Участник должен оценить необходимость раскрытия и порядок обработки данного материала."}, {"case_key": "bank-legal-2026-142", "title": "Чужое фото в партийной программе", "situation": "Партия включила чужую фотографию в печатную программу, не получив права использования. Указание автора она считает полноценной лицензией.\n\nФотограф разместил снимок в портфолио с условиями использования, отдельного разрешения партия не получала. Макет программы предусматривает печать 2 тыс. экземпляров и публикацию файла в сети. Дизайнер указал имя автора под изображением и считает вопрос закрытым. Участник получает макет и условия; решение требуется до заказа тиража."}, {"case_key": "bank-legal-2026-143", "title": "Секретный отзыв разрешения", "situation": "Орган отозвал разрешение предпринимателя, не указав основание и не предоставив предусмотренную возможность возражений. Причину обещают сообщить после закрытия деятельности.\n\nПредприниматель получил уведомление об отзыве, которое не содержит мотивов и порядка представления возражений. Деятельность требуют прекратить через два дня, материалы основания пока не раскрыты. В досье предусмотренная процедура участия адресата не проведена. Участник оценивает документ до наступления указанного срока."}, {"case_key": "bank-legal-2026-144", "title": "Две ответственности за один эпизод", "situation": "Два должностных лица одного органа независимо вынесли постановления по одному административному эпизоду в отношении того же лица. Оба постановления предполагают одинаковое наказание.\n\nОба постановления относятся к одному времени, месту, действию и одному привлекаемому лицу. Второй инспектор не проверил наличие первого решения в журнале органа. Заявитель представил обе копии и просит устранить двойное требование об оплате. Участник должен сопоставить эпизоды и определить дальнейшее действие по материалам."}, {"case_key": "bank-legal-2026-145", "title": "Изменение подсудности распоряжением", "situation": "Начальник ведомства решил, что все споры с его органом будет рассматривать выбранная им комиссия вместо суда. Заявителям рассылают обязательное распоряжение.\n\nВ распоряжении указано, что жалобы и судебные заявления граждан сначала должна окончательно разрешать ведомственная комиссия. Члены комиссии назначаются руководителем ответчика, независимого судебного рассмотрения документ не предусматривает. Заявителю отказали в направлении документов со ссылкой на распоряжение. Участник оценивает компетенцию органа и установленный способ защиты."}, {"case_key": "bank-legal-2026-146", "title": "Лишняя справка для услуги", "situation": "Центр госуслуг требует у заявителя справку, которую орган обязан получить межведомственно, и отказывается регистрировать заявление до её представления.\n\nЗапрошенная справка находится в государственном реестре и должна поступать по межведомственному каналу. Заявитель представил обязательные документы, а оператор требует принести справку лично на бумаге. Регистрация обращения откладывается, что влияет на дату предоставления услуги. Участник проверяет перечень и порядок обмена сведениями до отказа в приёме."}, {"case_key": "bank-legal-2026-147", "title": "Реквизиция без компенсации", "situation": "Для устранения последствий чрезвычайной ситуации орган изымает имущество и объявляет, что возврат или компенсация никогда не предусмотрены.\n\nВ чрезвычайной ситуации использован грузовой автомобиль частного владельца для доставки материалов. Орган зафиксировал изъятие, но в акте написал, что оценка стоимости, компенсация и последующий возврат исключены. Собственник просит сведения о состоянии автомобиля и основании дальнейшего удержания. Участник рассматривает акт и требования владельца после завершения срочных работ."}, {"case_key": "bank-legal-2026-148", "title": "Государственная помощь без контроля", "situation": "Получатель субсидии выполнил основную работу, но отказался от обязательной отчётности. Куратор предлагает не фиксировать нарушение, чтобы не ухудшать показатель ведомства.\n\nСоглашение о субсидии устанавливает отчёт о результатах, расходах и подтверждающих документах. Основной объект введён, но получатель письменно отказался представить обязательный отчёт в срок. Куратор предлагает отметить полный результат без материалов проверки. Участник должен выбрать действие для отчётности и контроля до закрытия периода."}, {"case_key": "bank-legal-2026-149", "title": "Ненормативный акт против закона", "situation": "Индивидуальный приказ министерства отменил право конкретного заявителя, прямо закреплённое законом. Орган считает, что более поздняя дата приказа даёт ему преимущество.\n\nЗаявитель предъявил норму закона, прямо предоставляющую право при выполненных условиях. Министерство выдало ему индивидуальный приказ об отказе со ссылкой только на более позднюю дату приказа. В приказе не указано изменение закона или иное предусмотренное основание. Участник рассматривает жалобу и должен определить соотношение документов."}, {"case_key": "bank-legal-2026-150", "title": "Вознаграждение за обязательную услугу", "situation": "Служащему предложили подарок за ускорение обязательного регистрационного действия. Он считает, что небольшая стоимость делает связь с услугой допустимой.\n\nПосетитель передал служащему подарочную карту на 5 тыс. ₽ и попросил поставить его заявление первым. Регистрационное действие входит в должностные обязанности, очередь уже установлена. Служащий ещё не использовал карту, но предлагает принять её как благодарность. Участник оценивает предложение и порядок дальнейших служебных действий до изменения очереди."}]$casecontext$::jsonb) as x(case_key text,title text,situation text))
update private.authored_event_catalog c set content=jsonb_set(jsonb_set(c.content,'{situation}',to_jsonb(x.situation)),'{title}',to_jsonb(x.title)) from context x where c.case_key=x.case_key;
update public.event_cases e set situation=c.content->>'situation',title=c.content->>'title' from private.authored_event_catalog c where e.case_key=c.case_key and e.case_key like 'bank-legal-2026-%' and not exists(select 1 from public.event_decisions d where d.case_id=e.id) and not exists(select 1 from public.event_case_outcomes o where o.case_id=e.id);
